<?php
if(PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$root = rtrim(getenv('MYSTEP_SOURCE') ?: dirname(__DIR__, 2), '/').'/';
$stage = rtrim(getenv('MYSTEP_STAGE') ?: '', '/');
spl_autoload_register(function($class) use($root,$stage) {
    $file = $stage !== '' && is_file($stage.'/lib/'.$class.'.class.php') ? $stage.'/lib/'.$class.'.class.php' : $root.'lib/'.$class.'.class.php';
    if(is_file($file)) require_once $file;
});
set_error_handler(function($number,$message,$file,$line){if(error_reporting()&$number)throw new ErrorException($message,0,$number,$file,$line);});
if(($argv[1] ?? '') === '--large') {
    $file = tempnam(sys_get_temp_dir(), 'mystep-excel-'); $stream = fopen($file, 'w+b');
    try {
        $xls = new myExcel(); $cell = str_repeat('x', 1024);
        for($i=0; $i<10000; $i++) { $xls->addRow(); $xls->addCells([$i,$cell]); }
        $bytes = $xls->writeTo($stream); fclose($stream); $stream = null;
        $reader = new XMLReader(); if(!$reader->open($file, null, LIBXML_NONET)) exit(2);
        $rows=0; while($reader->read()) if($reader->nodeType === XMLReader::ELEMENT && $reader->localName === 'Row') $rows++;
        $reader->close(); if($rows !== 10000 || $bytes < 10000000) exit(3);
        echo 'large-ok';
    } finally { if(is_resource($stream)) fclose($stream); unlink($file); }
    exit;
}
$passed=$failed=0;
function same($a,$b){if($a!==$b)throw new RuntimeException('Expected '.var_export($a,true).' got '.var_export($b,true));}
function check($value){if(!$value)throw new RuntimeException('Assertion failed');}
function raises($class,$run){try{$run();}catch(Throwable $e){if($e instanceof $class)return;throw $e;}throw new RuntimeException('Expected '.$class);}
function test($name,$run){global $passed,$failed;try{$run();$passed++;echo 'PASS '.$name.PHP_EOL;}catch(Throwable $e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage().PHP_EOL;}}
function xmlDoc($xml){$doc=new DOMDocument();if(!$doc->loadXML($xml,LIBXML_NONET))throw new RuntimeException('Invalid XML');return $doc;}
function sheetCells($xml,$sheet){$xp=new DOMXPath(xmlDoc($xml));$xp->registerNamespace('s','urn:schemas-microsoft-com:office:spreadsheet');$out=[];foreach($xp->query('//s:Worksheet') as $item)if($item->getAttributeNS('urn:schemas-microsoft-com:office:spreadsheet','Name')===$sheet){foreach($xp->query('s:Table/s:Row',$item) as $row){$cells=[];foreach($xp->query('s:Cell/s:Data',$row) as $cell)$cells[]=$cell->textContent;$out[]=$cells;}}return $out;}
class ExtensionTarget extends myBase {use myTrait {__destruct as public releaseTrait;}public $value='original';public static $shared='shared';public function __destruct(){}public function actual($v){return 'actual:'.$v;}public static function staticActual($v){return 'static:'.$v;}}
class ExtensionChild extends ExtensionTarget {}
class ExtensionSecret extends ExtensionTarget {protected $secret="keep";public function secret(){return $this->secret;}}
class ExtensionOther extends myBase {use myTrait;public function __destruct(){}}
class ExtensionParent {private $parentValue='default';public function setParent($v){$this->parentValue=$v;}public function parentValue(){return $this->parentValue;}}
class ExtensionState extends ExtensionParent {use myTrait;public static $calls=0;public $value='default';public function __construct($v='reset'){self::$calls++;$this->value=$v;}public function __destruct(){}}
class ExtensionError extends myBase {public function handler($f){$this->setErrHandler($f);}public function fail($m){return $this->error($m);}public function handlerValue(){return $this->err_handler;}}
class ExtensionMagicInit extends myBase {public $calls=0;public function __call($name,$args){$this->calls++;}}
class ExtensionRequired extends myBase {public $value='pending';public function init($v){$this->value=$v;}}
class ExtensionOptional extends myBase {public $calls=0,$value;public function init($v='default'){++$this->calls;$this->value=$v;}}
class ExtensionCallable {public function __invoke($v){return $v.'!';}public function method($v){return $v.'?';}}
try {
 test('base skips magic-only init dispatch',function(){$o=new ExtensionMagicInit();same(0,$o->calls);});
 test('base retains delayed required and initializes optional arguments once',function(){$a=new ExtensionRequired();same('pending',$a->value);$a->init('ready');same('ready',$a->value);$b=new ExtensionRequired('explicit');same('explicit',$b->value);$c=new ExtensionOptional();same(1,$c->calls);same('default',$c->value);});
 test('base errors restore global callback bits after default handler throws',function(){$o=new ExtensionError();$old=myException::$callback_type;$oldExit=myException::$exit_on_error;myException::$callback_type=E_WARNING;myException::$exit_on_error=false;try{raises(ErrorException::class,function()use($o){$o->fail('probe');});same(E_WARNING,myException::$callback_type);}finally{myException::$callback_type=$old;myException::$exit_on_error=$oldExit;}});
 test('base custom errors restore callback bits and support clearing a handler',function(){$o=new ExtensionError();$seen=[];$o->handler(function($msg)use(&$seen){$seen[]=$msg;});$old=myException::$callback_type;try{raises(ErrorException::class,function()use($o){$o->fail('custom');});same(['custom'],$seen);same($old,myException::$callback_type);$o->handler(null);same(null,$o->handlerValue());}finally{myException::$callback_type=$old;}});
 test('base invalid error handler preserves old callback',function(){$o=new ExtensionError();$f=function(){};$o->handler($f);raises(InvalidArgumentException::class,function()use($o){$o->handler('missing_extension_callback');});same($f,$o->handlerValue());});
 test('trait accepts named function extension without binding a string',function(){$o=new ExtensionTarget();$o->addMethod('strtoupper','upper');same('VALUE',$o->upper('value'));eval('namespace ExtensionFixtures; function upper($v) { return strtoupper($v); }');$o->addMethod('ExtensionFixtures\\upper');same('NAMESPACE',$o->upper('namespace'));});
 test('trait accepts object methods and callable objects unchanged',function(){$o=new ExtensionTarget();$target=new ExtensionCallable();$o->addMethod([$target,'method'],'method');$o->addMethod($target,'object');same('x?',$o->method('x'));same('x!',$o->object('x'));});
 test('trait supports bound and static closures and case insensitive extensions',function(){$o=new ExtensionTarget();$o->value='ready';$o->addMethod(function($v){return $this->value.$v;},'Joined');$o->addMethod(static function($v){return $v+1;},'step');same('ready!', $o->JOINED('!'));same(3,$o->step(2));});
 test('trait requires a name for closures and preserves extensions on failed registration',function(){$o=new ExtensionTarget();$o->addMethod(function(){return 'keep';},'kept');raises(InvalidArgumentException::class,function()use($o){$o->addMethod(function(){});});raises(InvalidArgumentException::class,function()use($o){$o->addMethod(12,'kept');});same('keep',$o->kept());});
 test('trait explicit extensions precede global function fallback',function(){$o=new ExtensionTarget();$o->addMethod(function(){return 'registered';},'strlen');same('registered',$o->strlen('abc'));same('ABC',$o->strtoupper('abc'));});
 test('trait callable closures created from internal functions remain usable',function(){$o=new ExtensionTarget();$o->addMethod(Closure::fromCallable('strlen'),'length');same(3,$o->length('abc'));});
 test('trait magic existence and removal do not expose or unset protected state',function(){$o=new ExtensionSecret();same(false,isset($o->secret));unset($o->secret);same('keep',$o->secret());});
 test('trait aliases work without a declared static table and reject cycles atomically',function(){ExtensionTarget::regAlias(['a'=>'b','b'=>'actual']);$o=new ExtensionTarget();same('actual:x',$o->a('x'));raises(InvalidArgumentException::class,function(){ExtensionTarget::regAlias(['b'=>'a']);});same('actual:y',$o->a('y'));same(null,(new ExtensionOther())->a('x'));});
 test('trait static aliases keep late static class and reject instance targets',function(){ExtensionChild::regAlias(['stat'=>'staticActual','bad'=>'actual']);same('static:x',ExtensionChild::stat('x'));raises(BadMethodCallException::class,function(){ExtensionChild::bad('x');});});
 test('trait dynamic null properties use consistent isset and unset semantics',function(){$o=new ExtensionTarget();$o->nil=null;same(null,$o->nil);same(false,isset($o->nil));$o->item='set';same(true,isset($o->item));unset($o->item);same(null,$o->item);});
 test('trait destructor leaves static and ordinary state intact',function(){$o=new ExtensionTarget();$o->releaseTrait();same('shared',ExtensionTarget::$shared);same('original',$o->value);});
 test('trait serialization keeps parent private values and never reruns constructor',function(){$o=new ExtensionState('saved');$o->setParent('private-saved');$calls=ExtensionState::$calls;$copy=unserialize(serialize($o));same($calls,ExtensionState::$calls);same('saved',$copy->value);same('private-saved',$copy->parentValue());});
 test('trait var_export rebuilds subclass without constructor side effects',function(){$o=new ExtensionChild();$o->value='saved';$copy=eval('return '.var_export($o,true).';');same(ExtensionChild::class,get_class($copy));same('saved',$copy->value);$calls=ExtensionState::$calls;$copy=ExtensionState::__set_state(['value'=>'restored']);same($calls,ExtensionState::$calls);same('restored',$copy->value);});
